bool GameData::uploadOne(Renderer& renderer) {if(assets->uploadOne(renderer))return true;if(terrain->uploadOne(renderer))return true;return false;}
GameLoading::GameLoading(Log& log) : log_(log),worker_([this](std::stop_token stop){run(stop);}) {}
GameLoading::~GameLoading() {{std::lock_guard lock(mutex_);worker_.request_stop();++generation_;}wake_.notify_one();}
std::uint64_t GameLoading::request(std::unique_ptr<ScriptSession> session) {if(!session || !session->configured() || !session->world())throw std::runtime_error("Cannot start unconfigured map");std::lock_guard lock(mutex_);auto id=++generation_;pending_=Request{id,std::move(session)};ready_.reset();phase_=0;wake_.notify_one();return id;}
void GameLoading::cancel() {std::lock_guard lock(mutex_);++generation_;pending_.reset();ready_.reset();}
std::optional<GameLoadResult> GameLoading::poll() {std::lock_guard lock(mutex_);auto result=std::move(ready_);ready_.reset();return result;}
void GameLoading::run(std::stop_token stop) {
    while(!stop.stop_requested()){Request request;{std::unique_lock lock(mutex_);wake_.wait(lock,[&]{return stop.stop_requested() || pending_.has_value();});if(stop.stop_requested())return;request=std::move(*pending_);pending_.reset();}auto started=GetTickCount64();auto stale=[&]{return stop.stop_requested() || generation_.load()!=request.id;};GameLoadResult result;result.request=request.id;
        try{auto game=std::make_unique<GameData>();game->session=std::move(request.session);auto checkpoint=[&,id=request.id]{if(stop.stop_requested() || generation_.load()!=id)throw std::runtime_error("Map load canceled");};checkpoint();phase_=1;try{auto preferences=loadAudioPreferences(game->session->world()->resources().root());game->session->localAudioGains(preferences.soundGain(),preferences.musicGain());game->session->localAudioCategories(preferences.ambient,preferences.movement,preferences.unitSounds);}catch(const std::exception& e){log_.write(std::string("audio_preferences_load_error=")+e.what());}game->session->startMain();checkpoint();phase_=2;auto walkablePrepared=game->session->prepareWalkableSurfaces(checkpoint,[&](const std::string& error){log_.write("walkable_prewarm_error="+error);});log_.write("walkable_prewarm_models="+std::to_string(walkablePrepared));checkpoint();game->assets=std::make_unique<SceneAssets>(game->session->world()->resources(),checkpoint);game->terrain=std::make_unique<TerrainScene>(*game->session->world(),*game->assets,log_);checkpoint();phase_=3;game->objects=std::make_unique<SceneObjects>(*game->session,*game->assets,log_);checkpoint();phase_=4;game->prepareConsole();game->assets->model(game->autocastModel,log_);if(!game->session->world()->environment().skyModel.empty())game->assets->model(game->session->world()->environment().skyModel,log_);for(auto& [id,item]:game->session->items())if(!item->icon.empty() && item->icon!="_")game->assets->image(item->icon);checkpoint();game->assets->clearCheck();if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll must not be loaded");log_.write("game_cpu_ready elapsed_ms="+std::to_string(GetTickCount64()-started)+" textures="+std::to_string(game->assets->uploadCount())+" chunks="+std::to_string(game->terrain->uploadCount())+" units="+std::to_string(game->session->units().size())+" game_dll_loaded=false");result.data=std::move(game);
        }catch(const std::exception& e){result.error=e.what();if(!stale())log_.write("game_load_failed="+result.error);}std::lock_guard lock(mutex_);if(!stale())ready_=std::move(result);
    }
}
